import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor gelu_forward(torch::Tensor x);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>

namespace {

constexpr float kGeluAlpha = 0.79788456080286535587989211986876f; // sqrt(2/pi)
constexpr float kGeluBeta  = 0.044715f;

__device__ __forceinline__ float gelu_scalar(float x) {
    float x3 = x * x * x;
    float inner = fmaf(kGeluBeta, x3, x);
    float t = tanhf(kGeluAlpha * inner);
    return 0.5f * x * (1.0f + t);
}

__global__ void gelu_tanh_vec4_kernel(const float* __restrict__ x,
                                      float* __restrict__ y,
                                      long long n) {
    const long long vec_n = n >> 2;
    const long long tid = static_cast<long long>(blockIdx.x) * blockDim.x + threadIdx.x;
    const long long stride = static_cast<long long>(gridDim.x) * blockDim.x;

    const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
    float4* __restrict__ y4 = reinterpret_cast<float4*>(y);

    for (long long i = tid; i < vec_n; i += stride) {
        float4 v = x4[i];
        v.x = gelu_scalar(v.x);
        v.y = gelu_scalar(v.y);
        v.z = gelu_scalar(v.z);
        v.w = gelu_scalar(v.w);
        y4[i] = v;
    }

    // Handle the remaining 0..3 scalar elements with the first block only.
    if (blockIdx.x == 0) {
        const long long tail = n & 3LL;
        if (static_cast<long long>(threadIdx.x) < tail) {
            const long long idx = (vec_n << 2) + threadIdx.x;
            y[idx] = gelu_scalar(x[idx]);
        }
    }
}

} // namespace

torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "gelu_forward expects a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "gelu_forward expects float32");

    auto xc = x.contiguous();
    auto y = at::empty_like(xc);

    const long long n = static_cast<long long>(xc.numel());
    if (n == 0) {
        return y;
    }

    constexpr int threads = 256;
    const long long vec_n = n >> 2;
    long long blocks = (vec_n + threads - 1) / threads;
    blocks = std::max<long long>(1, std::min<long long>(blocks, 65535));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    gelu_tanh_vec4_kernel<<<static_cast<unsigned int>(blocks), threads, 0, stream>>>(
        xc.data_ptr<float>(),
        y.data_ptr<float>(),
        n
    );

    return y;
}
"""

_gelu_ext = load_inline(
    name="gelu_tanh_fused_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["gelu_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    CUDA-fused tanh-approximation GELU:
      0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x):
        if not x.is_cuda:
            original_device = x.device
            return _gelu_ext.gelu_forward(x.cuda()).to(original_device)
        return _gelu_ext.gelu_forward(x)

